select case when c.credit_limit >= 17300 then 'high' when c.credit_limit >= 7800 then 'mid' else 'low' end as credit_limit_bucket, count(*) as web_event_count from web_events we join sessions s on we.session_id = s.id join customers c on s.customer_id = c.id where c.age > 35 group by case when c.credit_limit >= 17300 then 'high' when c.credit_limit >= 7800 then 'mid' else 'low' end order by credit_limit_bucket asc
